class ToyHashMap:
    """Separate chaining: each bucket is a list of [key, value] pairs."""

    def __init__(self, buckets=8):
        self.buckets = [[] for _ in range(buckets)]
        self.size = 0

    def _bucket(self, key):
        return self.buckets[hash(key) % len(self.buckets)]

    def put(self, key, value):
        bucket = self._bucket(key)
        for pair in bucket:
            if pair[0] == key:          # existing key: overwrite
                pair[1] = value
                return
        bucket.append([key, value])
        self.size += 1
        if self.size / len(self.buckets) > 0.75:
            self._resize()

    def get(self, key, default=None):
        for k, v in self._bucket(key):  # only scan one bucket
            if k == key:
                return v
        return default

    def _resize(self):
        pairs = [p for bucket in self.buckets for p in bucket]
        self.buckets = [[] for _ in range(2 * len(self.buckets))]
        self.size = 0
        for k, v in pairs:              # every key gets a new bucket
            self.put(k, v)

m = ToyHashMap()
for word in ["ant", "bee", "cat", "dog", "eel", "fox", "gnu"]:
    m.put(word, len(word))
print(m.get("cat"), m.get("yak"), len(m.buckets))   # 3 None 16

from collections import Counter, defaultdict

def letter_counts(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in t:
        if counts.get(ch, 0) == 0:
            return False                 # t has a letter s ran out of
        counts[ch] -= 1
    return True

print(letter_counts("banana"))           # {'b': 1, 'a': 3, 'n': 2}
print(Counter("banana").most_common(1))  # [('a', 3)]
print(is_anagram("listen", "silent"))    # True
print(is_anagram("rat", "car"))          # False

